def chunked(iterable, size, fill=None):
    it = iter(iterable)
    while True:
        chunk = []
        for _ in range(size):
            try:
                chunk.append(next(it))
            except StopIteration:
                break
        if not chunk:
            return
        if len(chunk) < size:
            chunk.extend([fill] * (size - len(chunk)))
        yield chunk

print(list(chunked(range(5), 3, fill=-1)))

def windows(seq, n):
    if n <= 0:
        raise ValueError('n must be positive')
    window = []
    for item in seq:
        window.append(item)
        if len(window) > n:
            window.pop(0)
        if len(window) == n:
            yield tuple(window)

print(list(windows([1, 2, 3, 4], 3)))

def flatten(iterable):
    for item in iterable:
        if isinstance(item, (list, tuple)):
            yield from flatten(item)
        else:
            yield item

print(list(flatten([[1, (2, 3)], [4, [5, 6]], 7])))

def cycle(iterable):
    saved = []
    for item in iterable:
        saved.append(item)
        yield item
    if not saved:
        return
    while True:
        for item in saved:
            yield item

gen = cycle('ab')
print([next(gen) for _ in range(5)])

class Countdown:
    def __init__(self, start):
        if start < 1:
            raise ValueError('start must be at least 1')
        self.current = start

    def __iter__(self):
        return self

    def __next__(self):
        if self.current < 1:
            raise StopIteration
        value = self.current
        self.current -= 1
        return value

print(list(Countdown(4)))

def read_lines_lazy(path):
    with open(path, 'r', encoding='utf-8') as f:
        for line in f:
            yield line.rstrip('\n')

