print(list(inorder(tree)))

def unique_everseen(iterable):
    seen = set()
    for item in iterable:
        if item not in seen:
            seen.add(item)
            yield item

print(list(unique_everseen(['b', 'a', 'b', 'c', 'a'])))

def peaks(seq):
    if len(seq) < 3:
        return
    for i in range(1, len(seq) - 1):
        if seq[i] > seq[i - 1] and seq[i] > seq[i + 1]:
            yield i, seq[i]

print(list(peaks([1, 3, 2, 5, 4, 4, 6])))

def zip_longest_gen(a, b, fill=None):
    a, b = iter(a), iter(b)
    while True:
        x = next(a, fill)
        y = next(b, fill)
        if x is fill and y is fill:
            return
        yield (x, y)

print(list(zip_longest_gen([1, 2, 3], ['a'], fill=None)))

def take_while(iterable, predicate):
    for item in iterable:
        if not predicate(item):
            break
        yield item

print(list(take_while([2, 4, 5, 6, 8], lambda x: x % 2 == 0)))

def drop_while(iterable, predicate):
    dropping = True
    for item in iterable:
        if dropping and predicate(item):
            continue
        dropping = False
        yield item

print(list(drop_while([1, 3, 5, 6, 7], lambda x: x % 2 == 1)))

def pairwise(iterable):
    it = iter(iterable)
    try:
        prev = next(it)
    except StopIteration:
        return
    for item in it:
        yield (prev, item)
        prev = item

print(list(pairwise('ABCDE')))

def round_robin(*iterables):
    iterators = [iter(it) for it in iterables]
    while iterators:
        for it in list(iterators):
            try:
                yield next(it)
            except StopIteration:
                iterators.remove(it)

print(list(round_robin('ABC', 'xy', '1234')))

from collections import deque

def bfs(graph, start):
    visited = {start}
    queue = deque([start])
    while queue:
        node = queue.popleft()
        yield node
        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append(neighbor)

graph = {'A': ['B', 'C'], 'B': ['D'], 'C': ['D', 'A'], 'D': []}
print(list(bfs(graph, 'A')))

def batched_flush(iterable, n):
    batch = []
    for item in iterable:
        batch.append(item)
        if len(batch) == n:
            yield batch
            batch = []
    if batch:
        yield batch

print(list(batched_flush(range(7), 3)))
